/* Tryvo local prototype. AI case reviews use the local Groq proxy; no accounts or remote analytics. */
(()=>{'use strict';
document.documentElement.classList.replace('no-js','js');
let lastRenderedHash=null;
const C=window.TryvoCampaign,R=window.TryvoRescue,A=window.TryvoArt,D=window.TryvoData,E=window.TryvoEngine,all=[...D.missions,D.check],legacy=D.legacy,KEY='tryvo-adventure-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=E.fresh(),storageOK=true,restoreBlocked=false,district='all',rankTask='archive',rankSupport='independent',showSamples=false,formError='',resultId=null,compareIds=[],query='',availability='all',toastTimer,filterTimer;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!E.valid(parsed,all,legacy))throw Error('Saved progress is incompatible.');state=parsed;}}catch(error){let existing=false;try{existing=!!localStorage.getItem(KEY);}catch{}restoreBlocked=existing;storageOK=false;}
function model(id,record){return (record&&record.contentVersion!==2?legacy:all).find(m=>m.id===id);}
state.surveys=state.surveys||{};state.surveyDrafts=state.surveyDrafts||{};
if(state.survey?.attempt&&!state.surveys[state.survey.attempt])state.surveys[state.survey.attempt]=state.survey;
if(state.surveyDraft?.attempt&&!state.surveyDrafts[state.surveyDraft.attempt])state.surveyDrafts[state.surveyDraft.attempt]=state.surveyDraft;
// Interaction patterns adapted from 50projects50days; see ATTRIBUTION.md.
const savedLibrary=state.library;
if(savedLibrary&&typeof savedLibrary==='object'){
 district=D.districts.some(d=>d.id===savedLibrary.district)?savedLibrary.district:'all';
 query=typeof savedLibrary.query==='string'?savedLibrary.query.slice(0,120):'';
 availability=['all','playable','completed','upcoming'].includes(savedLibrary.availability)?savedLibrary.availability:'all';
}

const prefs=state.dashboard&&typeof state.dashboard==='object'?state.dashboard:{};
let historyQuery=typeof prefs.query==='string'?prefs.query.slice(0,120):'',
 historyCondition=['all','independent','practice','check'].includes(prefs.condition)?prefs.condition:'all',
 historyTask=all.some(m=>m.id===prefs.task)?prefs.task:'all',recordCompare=[],historyExpanded=false;
rankTask=all.some(m=>m.id===prefs.rankTask)?prefs.rankTask:state.history.at(-1)?.taskId||'attendance';
rankSupport=['all','independent','practice'].includes(prefs.rankSupport)?prefs.rankSupport:'all';
showSamples=prefs.rankView==='examples';
function rememberDashboard(){state.dashboard={query:historyQuery,condition:historyCondition,task:historyTask,rankTask,rankSupport,rankView:showSamples?'examples':'records'};save();}
function dateText(r,dayOnly=false){const d=new Date(r.date);return Number.isNaN(d.getTime())?'Date unavailable':new Intl.DateTimeFormat(undefined,dayOnly?{day:'numeric',month:'short',year:'numeric'}:{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d);}
function modeText(r){return r.mode==='coop'?'Two players · one device':r.mode==='duel'?'Scripted duel':'Solo';}
function versionOf(r){return r.contentVersion||1;}
function recentRecords(){return [...state.history].sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0));}
function nextAction(){
 if(state.active&&state.active.phase!=='result')return {task:task(),label:'Resume investigation',action:'resume',why:'Your first take and evidence choices are saved. Pick up where you paused.'};
 const latest=recentRecords()[0];
 const checkNext=latest?.taskId==='attendance'&&!state.seen[D.check.id];
 const next=checkNext?D.check:D.missions.find(m=>!state.seen[m.id]);
 if(next)return {task:next,label:latest?'Try '+next.title:'Start my first mission',action:'start',why:checkNext?'You examined overlapping changes. Now interpret a different study design, without hints.':latest?'Explore an unopened story and practise '+next.skill.toLowerCase()+'.':'Make your first call, investigate the clues and decide what the evidence supports.'};
 if(!state.seen[D.check.id])return {task:D.check,label:'Try the independent check',action:'start',why:'A separate authored challenge in evaluating explanations. No hints before commitment.'};
 return {task:null,label:'Choose a story to revisit',action:'browse-library',why:'You have opened every available task. Revisit a story with a different approach; it will be labelled a replay and earn no new points.'};
}
function nextActionCard(compact=false){const n=nextAction();return `<section class="next-action ${compact?'compact-next':''}" aria-label="Your next step"><div class="next-art" aria-hidden="true">${A.scene(n.task?.id||'attendance')}</div><div class="next-copy"><span class="small-label">${n.action==='resume'?'Continue your investigation':state.history.length?'Your next discovery':'Start with a real choice'}</span><h2>${esc(n.task?.title||'A new approach to a familiar story')}</h2><p>${esc(n.why)}</p>${btn(esc(n.label),n.action,n.task?`data-id="${n.task.id}"`:'')}<span class="caption">${n.action==='resume'?'Resume your saved attempt':n.task?.type==='check'?'Separate check · no hints':n.task?'No timer · five playable stories':'More stories are upcoming'}</span></div></section>`;}
function contributionHighlight(m,r){
 const link=r.linkResults?.find(l=>l.points===20)||r.linkResults?.[0];
 if(!link)return 'You recorded a conclusion and selected '+r.pins.length+' sources under the earlier rubric.';
 const meaning=m.links.find(l=>l.id===link.id)?.options.find(o=>o.id===link.meaning)?.label;
 return `${link.points===20?'You supported':'Revisit your interpretation of'} “${m.evidence.find(e=>e.id===link.source)?.title}”: ${meaning}.`;
}
function partBars(r){return `<div class="part-bars" aria-label="Task rubric breakdown">${[['Conclusion','explanation',40],['Evidence','evidence',40],['Next step','next',20]].map(([label,key,max])=>`<div><span>${label}</span><meter aria-label="${label} points" min="0" max="${max}" value="${r.parts[key]}">${r.parts[key]} of ${max}</meter><strong>${r.parts[key]}/${max}</strong></div>`).join('')}</div>`;}
function inspectRecord(id){const r=state.history.find(r=>r.id===id);if(!r)return;const m=model(r.taskId,r);modal(esc(m.title),`<p class="caption">${esc(dateText(r))} · ${modeText(r)} · Content v${versionOf(r)}</p><p>${badge(support(r))}</p><h3 class="record-conclusion">${esc(m.options.find(o=>o.id===r.answer).label)}</h3>${partBars(r)}${connectionFeedback(m,r)}<p><strong>Next step:</strong> ${esc(m.nextOptions.find(o=>o.id===r.next).label)}</p><p class="caption">${r.score}/100 on this task; +${r.points} MindScore points. A task record, not an intelligence score.</p>${btn('View full contribution','history',`data-id="${esc(r.id)}"`,true)}`);}
function recordRow(r){const m=model(r.taskId,r);return `<article class="record-row"><div class="record-main"><time datetime="${esc(r.date)}">${esc(dateText(r))}</time><h3>${esc(m.title)}</h3><p>${esc(modeText(r))} · Content v${versionOf(r)}</p><p>${badge(support(r))}${m.type==='check'?' '+badge('Separate check','teal'):''}</p></div><div class="record-score"><strong>${r.score}<small>/100</small></strong>${partBars(r)}</div><div class="record-actions">${btn('Inspect reasoning','inspect-record',`data-id="${esc(r.id)}"` ,true)}<label class="compare-record"><input type="checkbox" data-record-compare value="${esc(r.id)}" ${recordCompare.includes(r.id)?'checked':''}> Compare<span class="sr-only"> this attempt: ${esc(m.title)}, ${esc(dateText(r))}</span></label></div></article>`;}
function compareRecords(){const records=recordCompare.map(id=>state.history.find(r=>r.id===id)).filter(Boolean);if(records.length!==2){say('Choose two attempts of the same task and content version.');return;}const [a,b]=records;if(a.taskId!==b.taskId||versionOf(a)!==versionOf(b)){say('Compare the same task and content version.');return;}const m=model(a.taskId,a);modal('Two attempts, in context',`<p>Same task: <strong>${esc(m.title)}</strong>. Content v${versionOf(a)}. Assistance and prior exposure may differ. A score difference alone does not demonstrate improvement.</p><div class="attempt-pair">${records.map(r=>`<article><h3>${esc(dateText(r))}</h3><p>${modeText(r)}</p><p>${badge(support(r))}</p><h3 class="record-conclusion">${r.score}/100</h3>${partBars(r)}<p>${esc(m.options.find(o=>o.id===r.answer).label)}</p>${connectionFeedback(m,r)}</article>`).join('')}</div>`);}
function comparisonTray(){return `<div class="comparison-tray"><span id="compare-record-status" role="status">${recordCompare.length} of 2 attempts selected. Same task and content version only.</span><button class="button secondary" data-action="compare-records" ${recordCompare.length!==2?'disabled':''}>Compare attempts</button><button class="text-button" data-action="clear-records">Clear selection</button></div>`;}
function filteredHistory(){return recentRecords().filter(r=>{const m=model(r.taskId,r);return (historyTask==='all'||r.taskId===historyTask)&&(historyCondition==='all'||historyCondition==='independent'&&r.eligible||historyCondition==='practice'&&!r.eligible||historyCondition==='check'&&m.type==='check')&&`${m.title} ${m.skill} ${modeText(r)} ${support(r)}`.toLowerCase().includes(historyQuery.trim().toLowerCase());});}
function historyRows(){const rows=filteredHistory();if(!rows.length)return `<div class="empty-state compact"><h3>${state.history.length?'No attempts match these filters.':'Your first contribution belongs here.'}</h3><p>${state.history.length?'Try another story, condition or search term.':'Finish a mission to see your decisions, feedback and practice conditions.'}</p>${state.history.length?btn('Clear history filters','clear-history','',true):btn('Start a mission','start','data-id="attendance"')}</div>`;let last='';const shown=historyExpanded?rows:rows.slice(0,matchMedia('(max-width:760px)').matches?3:10);return shown.map(r=>{const day=dateText(r,true),heading=day!==last?`<h3 class="date-group">${esc(day)}</h3>`:'';last=day;return heading+recordRow(r);}).join('')+(shown.length<rows.length?`<div class="history-more"><p class="caption">Showing the latest ${shown.length} of ${rows.length} matching attempts.</p>${btn('Show '+(rows.length-shown.length)+' more attempts','more-history','',true)}</div>`:'');}
function updateHistory(){if(!$('#history-records'))return;$('#history-records').innerHTML=historyRows();$('#history-count').textContent=`${filteredHistory().length} of ${state.history.length} recorded attempts`;}
function reflectionSummary(key,label){const values=state.history.map(r=>Number(state.surveys[r.id]?.[key])).filter(n=>n>=1&&n<=5),n=values.length;return `<article><h3>${label}</h3><p class="caption">${n} of ${state.history.length} attempts rated · ${state.history.length-n} unanswered</p><div class="rating-distribution" aria-label="${label} response distribution">${[1,2,3,4,5].map(value=>{const count=values.filter(v=>v===value).length;return `<div><span>${value}/5</span><meter aria-label="${label}: ${value} out of 5, response count" min="0" max="${Math.max(n,1)}" value="${count}">${count} responses</meter><strong>${count}</strong></div>`;}).join('')}</div><p class="caption">${n?'Counts of your optional responses.':'No responses yet. You can add one from a contribution record.'}</p></article>`;}

function toast(message){
 clearTimeout(toastTimer);const node=$('#toast');node.textContent=message;node.classList.add('visible');
 toastTimer=setTimeout(()=>{node.classList.remove('visible');node.textContent='';},4500);
}
function rememberLibrary(){state.library={district,query,availability};save();}
function filterLibrary(announce=false){
 if(!$('#mission-library'))return;
 const terms=query.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);
 let playable=0,upcoming=0;
 document.querySelectorAll('[data-library-entry]').forEach(node=>{
  const match=terms.every(t=>node.dataset.search.includes(t))&&(district==='all'||node.dataset.district===district)&&
   (availability==='all'||availability==='completed'&&node.dataset.completed==='true'||availability===node.dataset.availability);
  node.hidden=!match;
  if(match){if(node.dataset.availability==='upcoming')upcoming++;else playable++;}
 });
 document.querySelectorAll('.upcoming-group').forEach(g=>g.hidden=![...g.querySelectorAll('[data-library-entry]')].some(n=>!n.hidden));
 const details=$('.upcoming');details.hidden=!upcoming;
 if(query.trim()||availability==='upcoming')details.open=true;
 $('.mission-grid').hidden=!playable;
 $('#filter-empty').hidden=!!(playable+upcoming);
 const message=`${playable+upcoming} matching ${playable+upcoming===1?'mission':'missions'} · ${playable} playable · ${upcoming} upcoming`;
 $('#filter-count').textContent=message;
 $('#upcoming-count').textContent=`${upcoming} upcoming missions`;
 clearTimeout(filterTimer);if(announce)filterTimer=setTimeout(()=>say(message),250);
}
function reviewStage(stage,recordId){
 const r=recordId?state.history.find(r=>r.id===recordId):state.active;
 const m=model(r?.taskId,r);if(!m)return;
 if(stage==='first'&&r.initials.length){
  modal('Your recorded first take',r.initials.map((i,n)=>`<article><h3>${r.mode==='coop'?'Player '+(n+1):'Your starting judgment'}</h3><p>${esc(m.options.find(o=>o.id===i.answer).label)}</p><p>${esc(i.confidence)} confidence</p>${i.note?`<p class="personal-note">${esc(i.note)}</p>`:''}</article>`).join('')+'<p class="caption">This starting point stays unchanged. You can revise your final decision.</p>');
 }else if(stage==='evidence'&&r.phase==='result'){
  modal('Your recorded evidence',r.pins.map(id=>{const e=m.evidence.find(e=>e.id===id);return `<h3>${esc(e.title)}</h3>${evidenceBody(e)}`;}).join(''));
 }else if(stage==='decision'&&r.phase==='result'){
  modal('Your recorded decision',`<p>${esc(m.options.find(o=>o.id===r.answer).label)}</p><p>${esc(m.nextOptions.find(o=>o.id===r.next).label)}</p><div class="ungraded-note"><strong>Your personal note · not assessed</strong><p class="personal-note">${esc(r.note)}</p></div>`);
 }else if(stage==='evidence'&&r===state.active&&r.phase==='decision'){
  const f=$('#decision-form');if(f)draft(f);r.phase='investigate';r.decisionPanel='reasoning';r.turn=r.mode==='coop'?1:0;formError='';save();render();
 }
}
function refreshPoints(){document.querySelectorAll('#live-points,[data-live-points]').forEach(el=>el.textContent=window.TryvoRescueEngine.total(state));}
function save(){refreshPoints();if(!storageOK)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;notice();}}
function notice(){$('#notice').innerHTML=restoreBlocked?'<div class="notice">Saved progress could not be restored. The saved record has not been changed. <button data-action="fresh-session">Start a fresh session</button></div>':!storageOK?'<div class="notice">Progress cannot be saved on this device. You can continue this session.</div>':'';}
function say(t){$('#announcer').textContent=t;}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function task(){return model(state.active?.taskId,state.active);}
function icon(name,size=22){const paths={search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',route:'<path d="M4 18h5V6h7v12h4M2 18h4M18 18h4"/><circle cx="16" cy="6" r="2"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="m14 18 3 3 5-7"/>',chart:'<path d="M3 3v18h18M7 17v-5M12 17V8M17 17V4"/>',star:'<path d="m12 2 2.7 6.2L21 11l-6.3 2.8L12 20l-2.7-6.2L3 11l6.3-2.8Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.search}</svg>`;}
function btn(label,action,attrs='',secondary=false){return `<button class="button ${secondary?'secondary':''}" data-action="${action}" ${attrs}>${label}</button>`;}
function table(e){return e.table?`<div class="table-wrap"><table><caption class="sr-only">${esc(e.title)}</caption><thead><tr>${e.table.head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${e.table.rows.map(row=>`<tr>${row.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
function evidenceBody(e){return `<p>${esc(e.text)}</p>${table(e)}${e.note?`<div class="evidence-note">${icon('search',18)}<p>${esc(e.note)}</p></div>`:''}`;}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function support(r){const labels=[];if(r.mode==='coop')labels.push('Shared practice');if(r.replay)labels.push('Replay');if(r.hint)labels.push('Hint used');if(r.external)labels.push('Outside assistance declared');return labels.length?labels.join(' · '):'No assistance declared';}
function surface(title,subtitle,body){return `<section class="page"><div class="page-heading"><h1>${title}</h1><p>${subtitle}</p></div>${body}</section>`;}
function atlas(){const coords=[[41.3,46],[70.8,37],[43.8,81],[77.1,77],[87.5,27]];return `<div class="atlas" aria-label="Five districts on an illustrated island">${A.world()}${D.districts.map((d,i)=>{const done=state.history.some(r=>all.find(m=>m.id===r.taskId)?.district===d.id&&r.taskId!==D.check.id);return `<button class="atlas-node ${done?'district-visited':''}" style="--x:${coords[i][0]}%;--y:${coords[i][1]}%;--district:${d.color}" data-action="district" data-id="${d.id}" aria-label="Explore ${esc(d.name)}${done?', mission completed':''}"><span class="map-pin">${done?icon('check',14):'1'}</span><span>${esc(d.name)}</span><small>${done?'Mission completed':'1 playable mission'}</small></button>`;}).join('')}<span class="map-caption">Choose a district. Follow your curiosity.</span><span class="compass" aria-hidden="true">N<br>↑</span></div>`;}
function explore(){return C.home(state);}
function library(){const chosen=D.districts.find(d=>d.id===district);return `<section class="library page" id="mission-library"><a class="library-back" href="#demo">← Back to guided demo</a><div class="section-top"><div><span class="small-label">Choose a story to step into</span><h1>${chosen?esc(chosen.name):'Extra practice'}</h1></div><span class="availability">Five independent investigations</span></div><div class="filters" role="group" aria-label="Filter districts"><button class="filter ${district==='all'?'selected':''}" data-action="district" data-id="all" aria-pressed="${district==='all'}">All districts</button>${D.districts.map(d=>`<button class="filter ${district===d.id?'selected':''}" data-action="district" data-id="${d.id}" aria-pressed="${district===d.id}">${esc(d.short)}</button>`).join('')}</div><div class="library-tools"><label for="mission-search">Find your next challenge<input type="search" id="mission-search" maxlength="120" placeholder="Search stories, districts or skills" value="${esc(query)}" aria-describedby="filter-count"></label><label for="mission-availability">Show<select id="mission-availability">${[['all','All missions'],['playable','Playable (including replays)'],['completed','Completed'],['upcoming','Upcoming']].map(([v,l])=>`<option value="${v}" ${availability===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="text-button" data-action="reset-filters">Reset filters</button></div><p id="filter-count" class="caption"></p><div id="filter-empty" class="empty-state compact" hidden><h3>No matching stories.</h3><p>Try a different word, choose another district or reset your filters.</p><button class="button secondary" data-action="reset-filters">Show all missions</button></div><div class="mission-grid">${D.missions.map(m=>{const d=D.districts.find(x=>x.id===m.district),done=state.history.some(r=>r.taskId===m.id);return `<article class="mission-card" data-library-entry data-district="${d.id}" data-availability="playable" data-completed="${done}" data-search="${esc([m.title,m.skill,d.name,d.skill,d.short].join(' ').toLocaleLowerCase())}" style="--district:${d.color}"><div class="mission-art">${A.landmark(d.id)}${badge(done?'Completed':'Playable','light')}</div><div class="mission-card-body"><span class="small-label">${esc(d.name)}</span><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="card-foot"><span>${esc(d.short)}</span><button class="round-button" data-action="start" data-id="${m.id}" aria-label="${done?'Replay':'Start'} ${esc(m.title)}">${icon(done?'route':'arrow')}</button></div></div></article>`;}).join('')}</div><details class="upcoming"><summary>Stories still being written <span id="upcoming-count">20 upcoming missions</span></summary><p>These missions are not playable yet. They are not locked behind payment.</p><div class="upcoming-grid">${D.districts.map(d=>`<div class="upcoming-group"><h3>${esc(d.name)}</h3>${d.upcoming.map(n=>`<div class="upcoming-item" data-library-entry data-district="${d.id}" data-availability="upcoming" data-completed="false" data-search="${esc([n,d.name,d.skill,d.short].join(' ').toLocaleLowerCase())}">${icon('lock',14)}<span>${esc(n)}</span>${badge('Upcoming')}</div>`).join('')}</div>`).join('')}</div></details><div class="explore-note"><span>${icon('route',28)}</span><div><h3>The best discovery? What you brought to it.</h3><p>Make your first call, follow the evidence and see your thinking leave a trail. No timer. No streak to protect.</p></div></div></section>`;}
function steps(index,check=false,record=null){
 const a=record||state.active,labels=check?['Independent challenge','Your result']:['First take','Investigate','Decide','Your Contribution'];
 if(!check){if(index===2)index=3;else if(a?.phase==='decision')index=2;}
 const stages=['first','evidence','decision'];
 return `<nav class="mission-progress" aria-label="Mission progress"><ol class="steps">${labels.map((label,i)=>{
  const done=i<index,current=i===index,review=!check&&done&&(i===0&&a?.initials.length||i===1&&(a?.phase==='decision'||record)||i===2&&record);
  return `<li class="${done?'done':current?'current':'unavailable'}" ${current?'aria-current="step"':''}>${review?`<button data-action="review-stage" data-stage="${stages[i]}" ${record?`data-record="${record.id}"`:''} aria-label="Review ${label}">`:'<span class="step-content">'}<span class="step-marker" aria-hidden="true">${done?icon('check',14):i+1}</span><span>${label}<small>${done?'Completed · review':current?'Current step':'Not reached'}</small></span>${review?'</button>':'</span>'}</li>`;
 }).join('')}</ol></nav>`;
}
function options(list,name,value=''){return `<div class="choices">${list.map((o,i)=>`<label class="choice"><input type="radio" name="${name}" value="${o.id}" ${o.id===value?'checked':''}><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></label>`).join('')}</div>`;}
function context(m){return `${C.context(state,m.id)}<div class="mission-title"><a class="quiet-link" href="#explore">${icon('back',16)} Explore</a><span class="small-label">${esc(m.setting)}</span><h1>${esc(m.title)}</h1><p>${esc(m.subtitle)}</p></div>`;}
function character(m){const c={attendance:{name:'Mira',role:'Festival organiser',request:'Help me understand the empty seats.'},courtyard:{name:'Dev',role:'Neighbourhood coordinator',request:'Can we make this courtyard work for everyone?'},archive:{name:'Dev',role:'Archive coordinator',request:'This photograph needs to find its keeper.'},market:{name:'Dev',role:'Market organiser',request:'Which display deserves a second look?'},forecast:{name:'Dev',role:'Performance organiser',request:'We need a plan before the weather arrives.'}};return c[m.id]||{name:'Mira',role:'Librarian',request:'What changed around the library?'};}
function story(m,r){if(m.plan)return `<section class="story-page page"><span class="small-label">Your choice takes shape</span><h1>An investigation, designed by you.</h1><div class="story-conversation"><span class="avatar">${A.portrait()}</span><div><strong>Mira · festival organiser</strong><p>“This is the comparison you chose. Here is what it can help us learn, and what it leaves open.”</p></div></div>${planBoard(m,r.plan||r.planResult,true)}<div class="story-actions">${btn('Reveal my contribution','reveal')}<p>Your source connections are next.</p></div></section>`;const selected=m.nextOptions.find(n=>n.id===r.next).label,quotes={attendance:{separate:'I’ll compare price and transport access separately before changing the next event.',ask:'I’ll ask the people who stayed away, keeping in mind that memories and explanations can be imperfect.',likes:'I’ll look at poster engagement. That still leaves the price and transport questions unanswered.'},courtyard:{maintenance:'I’ll make the maintenance obligation visible alongside the plan.',best:'I’ll need to check whether our priorities match other neighbourhoods before generalising.',cheap:'The installation budget is only part of the picture. We still need to plan for upkeep.'},archive:{eliminate:'Noor has letters and Asha has maps. I can send the photograph to Dev.',window:'I’ll verify the collection assignments. A desk by a window is not enough evidence.',guess:'I’ll verify the collection assignments before sending the photograph.'},market:{random:'Let’s compare the displays with similar products and randomly assigned visitors.',bigger:'A larger banner does not separate the effects of the display, audience and product mix.',repeat:'More days help coverage, but the unequal audiences and products still need attention.'},forecast:{expected:'We’ll plan around expected cost, knowing a dry evening could still follow.',always:'We cannot guarantee a saving on this one evening. Expected cost describes repeated possibilities.',rain:'The forecast is a chance of heavy rain, not a fraction of the evening.'}};return `<section class="story-page page"><span class="small-label">Your decision moves the story forward</span><h1>A next step, shaped by you.</h1><div class="story-scene">${A.scene(m.id)}<span class="story-label">Authored scenario response</span></div><div class="story-conversation"><span class="avatar">${A.portrait(m.id==='attendance'?'mira':'dev')}</span><div><strong>${esc(character(m).name)}</strong><p>“${esc(quotes[m.id]?.[r.next]||m.consequence)}”</p></div></div><div class="story-decision"><span class="small-label">Your recommendation</span><p>${esc(selected)}</p><p class="caption">${esc(m.consequence)} No real booking, message or transaction occurs.</p></div><div class="story-actions">${btn('Reveal my contribution','reveal')}<p>See the decisions and evidence that got you here.</p></div></section>`;}
function comparison(){const a=state.active,m=task(),available=availableEvidence(m,a);compareIds=compareIds.filter(id=>available.some(e=>e.id===id));if(!compareIds.length)compareIds=available.slice(0,2).map(e=>e.id);const previousEvidence=a.evidence;compareIds.forEach(id=>E.view(a,m,id));a.evidence=previousEvidence;save();const body=`<p>Look for a difference, a connection or something neither clue tells you. Opening a clue does not earn reasoning credit.</p><div class="compare-controls">${available.map(e=>`<label><input type="checkbox" name="compare-clue" value="${e.id}" ${compareIds.includes(e.id)?'checked':''}>${esc(e.title)}</label>`).join('')}</div><div class="compare-pair">${compareIds.map(id=>{const e=m.evidence.find(e=>e.id===id);return `<article><div class="object-mini">${A.object(id)}</div><h3>${esc(e.title)}</h3>${evidenceBody(e)}</article>`;}).join('')}</div><p id="compare-status" class="caption" role="status">Select up to two clues. Your supporting evidence stays unchanged.</p>`;if($('#dialog').open){$('#dialog-content').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">Put the clues side by side.</h2><button class="close-button" data-action="close" aria-label="Close dialog">×</button></div>${body}`;}else modal('Put the clues side by side.',body);$('#dialog').classList.add('comparison-dialog');}
function modeLabel(a){return a.mode==='coop'?badge('Two investigators · one device'):a.mode==='duel'?badge('Simulated duel · scripted opponent'):'';}
function initial(m,a){return `<section class="mission-page">${context(m)}${steps(0)}<div class="brief-layout"><aside class="brief-scene"><div class="scene-illustration">${A.scene(m.id)}</div><div class="character-line"><span class="avatar">${A.portrait(m.id==='attendance'?'mira':'dev')}</span><span><strong>${esc(character(m).name)}</strong><small>${esc(character(m).role)} · fictional character</small></span></div><h2>${esc(character(m).request)}</h2><p>${esc(m.intro)}</p><div class="objective-card"><strong>Your mission</strong><p>${esc(m.skill)}. Make a recommendation you can support.</p></div><p class="caption">Illustrative scenario. All figures are authored.</p>${a.mode==='solo'&&(m.cooperative||m.duel)?`<div class="social-entry"><p>Want a different way to play?</p>${m.cooperative?btn(`${icon('people',18)} Play with a friend`,'switch-mode','data-mode="coop"',true):''}${m.duel?btn('Try a simulated duel','switch-mode','data-mode="duel"',true):''}<p class="caption">Changes mode within this attempt.</p></div>`:''}</aside><form id="initial-form" class="judgment-panel">${modeLabel(a)}${a.mode==='coop'?`<p class="small-label">Player ${a.turn+1}: your own first take</p>`:''}<h2>Before the clues, what’s your take?</h2><p>There’s room to change your mind. Start with an explanation you would investigate.</p><fieldset><legend>${esc(m.question)}</legend>${options(m.options,'initial',a.draftInitial?.answer)}</fieldset><fieldset><legend>How confident are you?</legend><div class="confidence">${['low','medium','high'].map(c=>`<label><input type="radio" name="confidence" value="${c}" ${a.draftInitial?.confidence===c?'checked':''}><span>${c[0].toUpperCase()+c.slice(1)}</span></label>`).join('')}</div></fieldset><label class="field-label" for="initial-note">Why do you think so? <span>Optional, not graded. Avoid personal information.</span></label><textarea id="initial-note" name="note" maxlength="600" placeholder="Put your first thought into words…">${esc(a.draftInitial?.note||'')}</textarea>${formError?`<p class="form-error" role="alert">${esc(formError)}</p>`:''}<div class="form-bottom"><span class="caption">Your first judgment stays in your contribution record.</span><button type="submit" class="button">Record my judgment</button></div>${a.replay?'<p class="caption">Replay: practise freely. This task cannot earn additional progress points.</p>':''}</form></div></section>`;}
function handoff(m,a){const initial=a.phase==='handoff-initial';return `<section class="handoff page">${icon('people',56)}<span class="small-label">Pass the device</span><h1>Over to Player 2.</h1><p>${initial?'Player 1’s judgment has been recorded. Make your own before you see the evidence.':'Player 1 has explored their evidence. You have a different set of clues. Pick the evidence you would bring to the conversation.'}</p><p class="caption">Shared-device practice. This handoff is not a private or secure separation.</p>${btn('I’m Player 2','handoff')}</section>`;}
function availableEvidence(m,a){return m.evidence.filter(e=>a.mode!=='coop'||a.phase==='decision'||e.group===a.turn);}
function investigation(m,a){const evid=availableEvidence(m,a);if(!evid.some(e=>e.id===a.evidence))a.evidence=evid[0].id;const e=evid.find(e=>e.id===a.evidence);if(!a.viewed[a.turn].includes(e.id)){E.view(a,m,e.id);save();}const initial=a.initials[a.turn];return `<section class="mission-page">${context(m)}${steps(1)}<details class="scene-ribbon-wrap"><summary>Mission brief and character</summary><div class="scene-ribbon"><div>${A.scene(m.id)}</div><p><strong>${esc(character(m).name)} is counting on your perspective.</strong><br>${esc(m.skill)}. Inspect the objects below and choose what supports your explanation.</p>${modeLabel(a)}</div></details><div class="workspace-top"><span>${badge(a.mode==='coop'?`Player ${a.turn+1}’s evidence`:'Your first judgment is recorded','teal')} ${modeLabel(a)}</span><span class="caption">${a.viewed[a.turn].length}/${evid.length} clues opened · ${a.pinned[a.turn].length} selected as support</span></div><div class="workspace"><details class="mobile-initial"><summary>My initial judgment</summary><p>${esc(m.options.find(o=>o.id===initial.answer).label)}</p><span class="caption">${esc(initial.confidence)} confidence</span></details><aside class="evidence-list"><h2>Follow the evidence</h2><p class="caption">Open a clue. Decide what matters.</p>${evid.map((x,i)=>`<button class="evidence-tab ${x.id===e.id?'active':''}" data-action="evidence" data-id="${x.id}" aria-pressed="${x.id===e.id}"><span class="clue-object">${A.object(x.id)}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.kind)}</small></span>${a.pinned[a.turn].includes(x.id)?icon('check',17):''}</button>`).join('')}</aside><article class="evidence-detail"><div class="evidence-object">${A.object(e.id)}</div><div class="sheet-top"><span>${esc(e.kind)}</span><span>Illustrative evidence</span></div><h2>${esc(e.title)}</h2>${evidenceBody(e)}<button class="pin-button ${a.pinned[a.turn].includes(e.id)?'pinned':''}" data-action="pin" data-id="${e.id}" aria-pressed="${a.pinned[a.turn].includes(e.id)}">${icon(a.pinned[a.turn].includes(e.id)?'check':'search',18)} ${a.pinned[a.turn].includes(e.id)?'Selected as supporting evidence':'Use as supporting evidence'}</button></article><aside class="judgment-sidebar"><details><summary>My starting point & selected evidence</summary><span class="small-label">My starting point</span><h3>${esc(m.options.find(o=>o.id===initial.answer).label)}</h3><span class="caption">${esc(initial.confidence)} confidence</span>${initial.note?`<p class="personal-note">${esc(initial.note)}</p>`:''}<div class="side-divider"></div><h3>What are you taking forward?</h3>${a.pinned[a.turn].length?`<ul class="selected-list">${a.pinned[a.turn].map(id=>`<li>${icon('check',16)}${esc(m.evidence.find(e=>e.id===id).title)}</li>`).join('')}</ul>`:'<p class="caption">Select evidence that supports or challenges your explanation.</p>'}</details><button class="text-button compare-launch" data-action="compare">Compare two clues</button><div class="hint-box">${a.hint?`<span class="small-label">Hint used</span><p>${esc(m.hint)}</p>`:`<button class="text-button" data-action="hint">Need a nudge?</button><p class="caption">Get guidance when it helps. Your practice and contribution are still recorded; this attempt will not earn independent points.</p>`}</div></aside></div>${a.mode==='coop'?connections(m,a):''}${formError?`<p class="form-error" role="alert">${esc(formError)}</p>`:''}<div class="action-bar"><span>${a.hint?'Hint used':a.replay?'Replay':a.mode==='duel'?'Scripted opponent · no timer':'Take your time. There is no timer.'}</span>${btn(a.mode==='coop'&&a.turn===0?'Pass to Player 2':'Form my decision','decide')}</div></section>`;}
function decision(m,a,check=false){
 const pins=a.mode==='coop'?[...new Set(a.pinned.flat())]:a.pinned[0],building=m.plan&&a.decisionPanel==='plan';
 const reasoning=`<fieldset><legend>${esc(m.question)}</legend>${options(m.options,'answer',a.answer)}</fieldset>${m.links?connections(m,a,a.mode==='coop'):''}`;
 const note=`<label class="field-label" for="final-note">Personal note <span>Optional and ungraded; not included in the result. Avoid personal information.</span></label><textarea id="final-note" name="note" maxlength="600" placeholder="What changed your mind, or supported your first take?">${esc(a.note)}</textarea><label class="check-label"><input type="checkbox" name="external" ${a.external?'checked':''}> I used outside help, including AI, during this attempt.</label><p class="caption">Self-reported assistance. This prototype cannot certify independence.</p>`;
 return `<section class="mission-page">${context(m)}${steps(check?0:1,check)}<div class="decision-layout"><aside class="decision-context">${!check?`<details class="source-desk" ${matchMedia('(min-width:761px)').matches?'open':''}><summary>Selected evidence · ${pins.length} sources</summary>`:''}<h2>${check?'A fresh situation':'Your source desk'}</h2>${check?`<p>${esc(m.intro)}</p><p class="caption">No hints or interpretation feedback before commitment.</p>${m.evidence.map(e=>`<article class="check-evidence"><span class="small-label">${esc(e.kind)}</span><h3>${esc(e.title)}</h3>${evidenceBody(e)}<button class="pin-button ${pins.includes(e.id)?'pinned':''}" data-action="pin-check" data-id="${e.id}" aria-pressed="${pins.includes(e.id)}">${icon(pins.includes(e.id)?'check':'search',16)}${pins.includes(e.id)?'Supporting evidence selected':'Select supporting evidence'}</button></article>`).join('')}`:pins.map(id=>{const e=m.evidence.find(x=>x.id===id);return `<details class="evidence-summary"><summary>${esc(e.title)}</summary>${evidenceBody(e)}</details>`;}).join('')}${!check?btn('Review evidence','back-evidence','',true):''}${building?`<div class="decision-recap"><span class="small-label">Your current conclusion</span><p>${esc(m.options.find(o=>o.id===a.answer)?.label)}</p>${btn('Review my interpretation','review-interpretation','',true)}</div>`:''}${!check?'</details>':''}</aside><form id="decision-form" class="judgment-panel">${badge(check?'Independent challenge':a.mode==='coop'?'Shared decision':'Your decision','teal')}${m.plan?`<div class="decision-substeps"><span class="${building?'':'active'}">1 · Interpret the evidence</span><span class="${building?'active':''}">2 · Design the comparison</span></div>`:''}<h2>${building?'What should Mira compare next?':check?'What can you conclude?':'Where does the evidence take you?'}</h2><p>${building?'Turn your conclusion into an investigation.':check?'Choose what the records establish and where their limits are.':'Keep or revise your view. Show which sources support it.'}</p>${building?planner(m,a):reasoning}${!m.plan?`<fieldset><legend>${esc(m.nextQuestion)}</legend>${options(m.nextOptions,'next',a.next)}</fieldset>`:''}${!m.plan||building?note:''}${formError?`<p class="form-error" role="alert">${esc(formError)}</p>`:''}${m.plan&&!building?`<button class="button" type="button" data-action="build-plan">Build my investigation plan</button><p class="caption">Your choices are saved. Feedback comes after you commit the plan.</p>`:`<button class="button" type="submit">${check?'Submit my reasoning':'Commit my decision'}</button>`}</form></div></section>`;
}

function contributionText(m,r){return m.links?'These are the sources you selected. Your interpretations are checked in the connection feedback below.':'Earlier rubric: this record captures evidence selection, not evidence of understanding.';}
function connectionQuestion(m,l){
 const prompts={attendance:{overlap:'What changed before the event?',groups:'How did participation differ?'},market:{rates:'How do the two stalls compare?',causal:'What limits a causal conclusion?'},forecast:{chance:'How should uncertainty enter the decision?',cost:'Which financial comparison matters?'},'library-check':{design:'What makes the groups informative?',difference:'How large is the observed difference?'}};
 return prompts[m.id]?.[l.id]||l.title;
}
function connections(m,a,sharedReview=false){
 if(!m.links)return '';
 const pins=a.mode==='coop'?[...new Set(a.pinned.flat())]:a.pinned[0];
 const links=a.mode==='coop'&&!sharedReview?m.links.filter(l=>l.owner===a.turn):m.links;
 const openId=links.some(l=>l.id===a.connectionOpen)?a.connectionOpen:(links.find(l=>!a.reasoning?.[l.id]?.source||!a.reasoning?.[l.id]?.meaning)||links[0]).id;
 return `<section class="connection-work"><div class="connection-heading"><span>${icon('route',22)}</span><div><h2>${sharedReview?'What each investigator found':'Build your evidence connections'}</h2><p>Pair a clue with what you believe it establishes. Feedback waits until you commit.</p></div></div><p class="connection-count caption">${links.filter(l=>a.reasoning?.[l.id]?.source&&a.reasoning?.[l.id]?.meaning).length} of ${links.length} connections recorded</p>${links.map((l,i)=>{
 const v=a.reasoning?.[l.id]||{},source=m.evidence.find(e=>e.id===v.source),available=m.evidence.filter(e=>a.mode!=='coop'||e.group===l.owner);
 return `<details class="connection-editor" name="evidence-connections" data-link="${l.id}" ${l.id===openId?'open':''}><summary><span>Connection ${a.mode==='coop'?l.owner+1:i+1}${a.mode==='coop'?' · Player '+(l.owner+1):''}</span><strong data-link-status>${v.source&&v.meaning?'Recorded':'Needs your input'}</strong></summary><fieldset class="connection-card"><legend>${esc(connectionQuestion(m,l))}</legend>${sharedReview?`<p><strong>${esc(source?.title||'No source selected')}</strong></p><p>${esc(l.options.find(o=>o.id===v.meaning)?.label||'No interpretation recorded')}</p><span class="caption">Recorded by Player ${l.owner+1}. Retained for the shared decision.</span>`:`<label for="source-${l.id}">Choose your source<select id="source-${l.id}" data-connection="${l.id}" data-part="source" aria-describedby="source-help-${l.id}"><option value="">Choose a source</option>${available.map(e=>`<option value="${e.id}" ${v.source===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label><span id="source-help-${l.id}" class="caption">${a.mode==='coop'?'All clues assigned to you are available.':'All mission clues are available.'} Choosing a source also adds it to your supporting evidence.</span><div class="selected-source" id="preview-${l.id}">${source?`<details><summary>Read ${esc(source.title)}</summary>${evidenceBody(source)}</details>`:'<p>Select a source to keep its contents beside your interpretation.</p>'}</div><fieldset class="interpretation-options"><legend>What can you infer?</legend>${l.options.map(o=>`<label class="interpretation-choice"><input type="radio" name="meaning-${l.id}" value="${o.id}" data-connection="${l.id}" data-part="meaning" ${v.meaning===o.id?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}</fieldset>`}</fieldset></details>`;
 }).join('')}<p class="caption">“Recorded” means filled in, not correct. Personal notes are never graded.</p></section>`;
}
function planBoard(m,plan={},reveal=false){
 const f=m.plan.factors.find(f=>f.id===plan.factor),g=m.plan.groups.find(g=>g.id===plan.groups);
 return `<div class="plan-board"><div class="plan-board-title">${icon('grid',22)}<strong>${reveal?'Mira’s investigation board':'Your investigation board'}</strong>${badge(reveal?'Authored plan feedback':'Preview · no result yet')}</div><div class="plan-groups"><article><span>Group A</span><h3>${esc(f?.a||'Choose what changes')}</h3><p>${esc(f?.held||'The comparison appears as you choose.')}</p></article><span class="versus" aria-hidden="true">↔</span><article><span>Group B</span><h3>${esc(f?.b||'Choose a comparison')}</h3><p>${esc(f?.held||'Two groups, one question.')}</p></article></div><p class="assignment-line">${g?esc(g.label):'Choose how invitees enter each group.'}</p>${reveal&&f&&g?`<div class="plan-feedback"><h3>${f.id!=='bundle'&&g.id==='random'?'A comparison that can separate one factor':'This plan leaves a source of ambiguity'}</h3><p>${esc(f.why)}</p><p>${esc(g.detail)}</p><p>Track attendance for everyone assigned, whether or not they use the offer. No experiment is run here and no future attendance is predicted.</p></div>`:''}</div>`;
}
function planner(m,a){return `<section class="planner"><h2>Give Mira an investigation she can use.</h2><p>Choose an offer and a way to form groups. The board follows your choices.</p><label for="plan-factor">What will change?<select id="plan-factor" data-plan="factor"><option value="">Choose an offer</option>${m.plan.factors.map(f=>`<option value="${f.id}" ${a.plan?.factor===f.id?'selected':''}>${esc(f.label)}</option>`).join('')}</select></label><label for="plan-groups">How will you form groups?<select id="plan-groups" data-plan="groups"><option value="">Choose a grouping method</option>${m.plan.groups.map(g=>`<option value="${g.id}" ${a.plan?.groups===g.id?'selected':''}>${esc(g.label)}</option>`).join('')}</select></label><div id="plan-preview" aria-live="polite">${planBoard(m,a.plan)}</div></section>`;}
function connectionFeedback(m,r){
 if(!r.linkResults)return '';
 const planRecord=r.planResult?`<details class="saved-plan"><summary>Your investigation plan · ${r.planResult.points}/20 for the next step</summary>${planBoard(m,r.plan||r.planResult,true)}</details>`:'';
 return `<section class="connection-feedback"><div class="section-top"><h2>What your connections established</h2><span class="caption">Structured choices, checked against this task</span></div>${r.linkResults.map(lr=>{const l=m.links.find(l=>l.id===lr.id),good=lr.points===20;return `<article class="feedback-item ${good?'supported':'revisit'}"><span class="feedback-icon">${icon(good?'check':'search',20)}</span><div><span class="small-label">${r.mode==='coop'?'Player '+(lr.by+1)+' · ':''}${good?'Supported connection':'A connection to revisit'}</span><h3>${esc(m.evidence.find(e=>e.id===lr.source).title)}</h3><p><strong>Your interpretation:</strong> ${esc(l.options.find(o=>o.id===lr.meaning).label)}</p><p>${!lr.sourceOK?'The chosen source does not establish that relationship. ':''}${esc(l.why)}</p></div></article>`;}).join('')}<p class="caption">These checks assess source–interpretation pairs. They do not evaluate your free-text notes or measure general ability.</p>${planRecord}</section>`;
}
function nextPractice(m,r){
 if(C.chapter(m.id)&&r.contentVersion===2)return C.handoff(state,m.id)+(m.id==='attendance'?`<aside class="assessment-link next-card"><p>Optional: try a different evidence structure without hints. This check stays separate from festival completion.</p>${btn(state.seen[D.check.id]?'Revisit the independent check':'Try the independent check','start','data-id="library-check"',true)}</aside>`:'');
 const target=m.id==='attendance'?D.check:m.id==='library-check'?D.missions.find(m=>m.id==='market'):D.missions.find(m=>!state.seen[m.id]);
 if(state.active&&state.active.phase!=='result')return nextActionCard(true);
 const revisit=r.linkResults?.some(l=>l.points<20);
 return `<div class="practice-next next-card"><div><h3>${target?m.id==='attendance'?'Try a different study design.':'Take your thinking into another story.':'Choose a new approach to a familiar story.'}</h3><p>${revisit?'There is a connection to revisit in the feedback below. ':''}${target?state.seen[target.id]?'You have opened this task before. Another attempt is a replay, not an unfamiliar test.':target.type==='check'?'This separate task has different evidence and no hints before commitment.':'This story is unopened in your local record.':'All district stories have been opened. Replays record practice without new points.'}</p><span class="caption">A task-based suggestion, not a claim about your ability.</span></div>${btn(target?(state.seen[target.id]?'Revisit ':'Try ')+esc(target.title):'Explore the stories',target?'start':'explore',target?`data-id="${target.id}"`:'')}</div>`;
}
function campaign(){
 const route=['attendance','library-check','market'],done=id=>state.history.some(r=>r.taskId===id&&r.contentVersion===2),next=route.find(id=>!done(id));
 return `<section class="practice-route page"><div class="route-intro"><div><span class="small-label">A short practice route</span><h2>From a hunch to a defensible decision.</h2><p>Three situations. Choose your next step, or explore freely.</p></div>${next?btn('Continue the route','start',`data-id="${next}"`,true):badge('Route explored · revisit any story','teal')}</div><ol>${route.map((id,i)=>{const m=all.find(m=>m.id===id);return `<li class="${done(id)?'route-done':''}"><span>${done(id)?icon('check',18):i+1}</span><div><h3>${esc(m.title)}</h3><p>${['Separate what happened from why','Interpret a different study design','Compare rates before choosing a display'][i]}</p><button class="text-button" data-action="start" data-id="${id}">${done(id)?'Revisit':'Enter story'}</button></div></li>`;}).join('')}</ol><p class="caption">Completion records practice, not proven learning. The independent task has no hints; previously opened tasks are labelled replays.</p></section>`;
}
function rival(m,r){
 if(!m.links)return '';
 const sample=sampleRecord(m,false),same=r.answer===sample.answer;
 return `<div class="rival-panel"><h3>Why did your approaches differ?</h3><p class="caption">Authored opponent. No live player or matchmaking.</p><div class="rival-columns"><article><strong>Your approach</strong><p>${esc(m.options.find(o=>o.id===r.answer).label)}</p><p>${r.parts.evidence}/40 for source–interpretation connections</p></article><article><strong>Scripted opponent</strong><p>${esc(m.options.find(o=>o.id===sample.answer).label)}</p><p>${sample.parts.evidence}/40 for source–interpretation connections</p></article></div><p>${same?'You chose the same conclusion. Compare the connections used to reach it.':'Your conclusions differ. Inspect the source connections before deciding which is supported.'}</p><details><summary>Inspect the opponent’s reasoning</summary>${connectionFeedback(m,sample)}</details></div>`;
}
function sampleRecord(m,strong=true){
 const reasoning={};m.links.forEach((l,i)=>reasoning[l.id]={source:l.sources[0],meaning:strong||i===0?l.correct:l.options.find(o=>o.id!==l.correct).id,by:0});
 const answer=m.options.find(o=>o.points===40).id,next=m.nextOptions.find(o=>o.points===20).id;
 const response={reasoning,plan:{factor:'transport',groups:'random'}};
 return {...response,...E.grade(m,answer,next,m.evidence.map(e=>e.id),response)};
}
function sampleComparison(m){return `<section class="sample-rankings"><h3>Same answer. Different support.</h3><p>Fictional examples using this revision’s rubric. No live users; these never enter your history or MindScore.</p><div class="rival-columns">${[true,false].map((strong,i)=>{const sample=sampleRecord(m,strong);return `<article><h3>Sample ${i===0?'A':'B'} · ${sample.score}/100</h3><p>${esc(m.options.find(o=>o.id===sample.answer).label)}</p><p>${sample.parts.evidence}/40 for evidence connections</p><details><summary>See the reasoning</summary>${connectionFeedback(m,sample)}</details></article>`;}).join('')}</div></section>`;}

function result(m,r){const initial=r.initials[0],first=m.options.find(o=>o.id===initial?.answer),final=m.options.find(o=>o.id===r.answer);const isCheck=m.type==='check';return `<section class="mission-page result-page">${context(m)}${r.contentVersion!==2?'<p class="notice">Earlier content and rubric preserved. This result is not compared with revised missions.</p>':''}${steps(isCheck?1:2,isCheck,r)}<div class="result-intro"><div class="result-seal">${icon('route',30)}</div><div><span class="small-label">${isCheck?'A separate task result':'The outcome is part of the story'}</span><h2>${isCheck?'Here’s how you reasoned.':'Your Contribution'}</h2><p>${isCheck?'This is evidence about one task, not a measure of general ability.':'Your first take. Your clues. Your call. Here is the trail you left.'}</p></div></div><div class="contribution-highlight"><h3>${esc(contributionHighlight(m,r))}</h3><p class="caption">${esc(support(r))} · ${esc(dateText(r))}</p></div>${nextPractice(m,r)}<div class="contribution-layout"><div><details class="result-detail"><summary>Your decision trail</summary><div class="contribution-stamp"><span>${icon('check',18)} Attempt recorded</span><span>Every choice has a place in the story.</span></div><div class="reasoning-trail">${!isCheck?`<article class="trail-start"><span class="trail-dot"></span><span class="small-label">${r.mode==='coop'?'Player 1’s first take':'Your first take'}</span><h3>${esc(first?.label||'Not recorded')}</h3><span class="caption">${esc(initial?.confidence||'')} confidence</span>${initial?.note?`<p class="personal-note">${esc(initial.note)}</p>`:''}</article>`:''}<article><span class="trail-dot"></span><span class="small-label">Evidence you brought forward</span><div class="contribution-evidence">${r.pins.map(id=>{const e=m.evidence.find(e=>e.id===id);return `<button data-action="inspect" data-id="${id}" data-task="${m.id}">${icon('search',16)}${esc(e.title)}</button>`;}).join('')}</div><p>${esc(contributionText(m,r))}</p></article><article><span class="trail-dot final-dot"></span><span class="small-label">${isCheck?'Your conclusion':r.mode==='coop'?'Your shared decision':first?.id===final.id?'You kept your explanation':'You revised your explanation'}</span><h3>${esc(final.label)}</h3><p>${esc(m.nextOptions.find(n=>n.id===r.next).label)}</p>${r.note?`<div class="ungraded-note"><strong>Your personal note · not assessed</strong><p class="personal-note">${esc(r.note)}</p></div>`:''}</article></div>${r.mode==='coop'?`<div class="partner-record"><h3>Both perspectives, kept separate</h3>${r.initials.map((i,n)=>`<div><strong>Player ${n+1}</strong><p>Started with: ${esc(m.options.find(o=>o.id===i.answer).label)}</p><p>Selected: ${r.pinned[n].map(id=>esc(m.evidence.find(e=>e.id===id).title)).join(', ')||'No evidence selected'}</p></div>`).join('')}<p class="caption">The task score describes the shared decision, not either player’s independent ability.</p></div>`:''}</details><details class="result-detail"><summary>Source connections and investigation feedback</summary>${connectionFeedback(m,r)}</details><details class="result-detail"><summary>What the evidence supports</summary><div class="explanation"><h3>${isCheck?'The reasoning behind this task':'What the evidence supports'}</h3><p>${esc(m.explanation)}</p></div></details><details class="consequence"><summary>${isCheck?'What this result means':'What happens in this scenario'}</summary><p>${esc(m.consequence)}</p></details></div><aside class="result-sidebar"><div class="score-card"><span class="small-label">${r.mode==='coop'?'Shared task result':'This task result'}</span><div class="task-score">${r.score}<span>/100</span></div><p>Structured-choice result · authored rubric</p><dl><div><dt>Explanation</dt><dd>${r.parts.explanation}/40</dd></div><div><dt>${m.links?'Evidence connections':'Evidence selection (earlier rubric)'}</dt><dd>${r.parts.evidence}/40</dd></div><div><dt>Next step</dt><dd>${r.parts.next}/20</dd></div></dl>${badge(support(r))}<div class="points-line"><span>MindScore added</span><strong>+${r.points}</strong></div><p class="caption">${r.eligible?'First attempt, no assistance declared.':'Practice recorded. '+(r.mode==='coop'?'Shared work does not earn independent credit.':r.replay?'Replays do not earn points again.':'Assisted attempts do not earn progress points.')} MindScore tracks game progress, not intelligence or improvement.</p></div>${r.mode==='duel'&&m.links?rival(m,r):''}${r.mode==='duel'&&!m.links?`<div class="duel-result"><h3>Your simulated duel</h3><p>You: <strong>${r.score}</strong><br>Scripted opponent: <strong>60</strong></p><p class="caption">Fixed demonstration opponent. No live player, no speed bonus. A tie is possible.</p></div>`:''}</aside></div>${survey(r)}</section>`;}
function survey(r){const existing=!!state.surveys[r.id],response=state.surveyDrafts[r.id]||state.surveys[r.id]||{};return `<form id="survey-form" class="survey"><div><span class="small-label">Two different questions</span><h2>How did this attempt feel?</h2><p>Optional, about this attempt only. Enjoyment and earned satisfaction are separate; neither changes your score.</p></div><fieldset><legend>How much did the achievement feel earned through your own contribution?</legend><div class="ratings">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="earned" value="${n}" ${response.earned===String(n)?'checked':''}><span>${n}</span></label>`).join('')}</div><span class="rating-ends"><span>Not at all</span><span>Very much</span></span></fieldset><fieldset><legend>How enjoyable was the experience?</legend><div class="ratings">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="enjoyment" value="${n}" ${response.enjoyment===String(n)?'checked':''}><span>${n}</span></label>`).join('')}</div><span class="rating-ends"><span>Not enjoyable</span><span>Very enjoyable</span></span></fieldset><div class="survey-actions"><button type="submit" class="button">${existing?'Update reflection':'Save reflection'}</button>${btn('Skip reflection · explore','explore','',true)}</div><span class="caption" id="survey-status">${existing?(storageOK?'Reflection saved on this device.':'Reflection recorded for this session only.'):''}</span></form>`;}
function levelReport(c,records){
 const r=records.at(-1),route=c.type==='route';
 const currentDraft=route?state.tram?.drafts[c.id]:null,currentCase=currentDraft&&['obstacle','puzzle'].some(k=>currentDraft[k]?.case?.review&&currentDraft[k].case.sessionId!==r?.[k]?.case?.sessionId)?window.TryvoCases.receipt({level:c.id,...currentDraft}):'';
 if(!r&&currentCase)return `<p class="level-empty">Your case work is saved. Complete the tram journey to finish this level.</p>${currentCase}`;
 if(!r)return `<p class="level-empty">No completed ${route?'test runs':'attempts'} yet.${state.active?.taskId===c.id&&state.active.phase!=='result'?' Your current attempt is still in progress.':''}</p>`;
 const m=route?null:model(c.id,r),meaning=route?(r.success?`${r.passengers??'Your'} passengers delivered. ${r.economyVersion===1?r.distance+' km · '+r.net+' operating net.':''}`:r.message||window.TryvoRescueEngine.evaluate(window.TryvoRescueEngine.level(c.id),r.path).message):m.options.find(o=>o.id===r.answer)?.label;
 const openRecord=(x,label)=>route?`<button class="text-button" data-rescue="watch-record" data-record="${esc(x.id)}">${label}</button>`:btn(label,'inspect-record',`data-id="${esc(x.id)}"`,true);
 return `<div class="level-latest"><div class="level-report-heading"><strong>Latest ${route?'test run':'attempt'}</strong><time datetime="${esc(r.date)}">${esc(dateText(r))}</time></div><p class="level-conclusion">${esc(meaning)}</p>
 ${route?`<dl class="route-report-stats"><div><dt>Route cost</dt><dd>${r.cost} credits</dd></div><div><dt>Connected streets</dt><dd>${r.path.length-1}</dd></div><div><dt>Test result</dt><dd>${r.success?'Arrived':'Revise route'}</dd></div></dl>${r.destination?`<p class="caption">Destination recorded: ${esc(r.destination)}</p>`:''}<p class="caption">${r.hint?'Nudge used':'No in-game nudge used'}${!r.success&&C.done(state,c.id)?' · An earlier successful run counts toward completion.':''}</p>`:`${partBars(r)}<p class="caption">${esc(modeText(r))} · ${esc(support(r))}${r.contentVersion!==2?' · Earlier content version':''}</p><p class="level-feedback">${r.score===100?'All three parts are supported by this task’s rubric.':'Review the feedback to see which parts of your reasoning need another look.'}</p>`}
 ${route&&r.economyVersion===1?`<p class="route-earnings">Fares ${r.revenue} − costs ${r.cost} = ${r.net} operating net. ${r.success?'Final rebate +'+r.rebate+' · settled balance '+r.settledBalance+'.':''}</p><p class="caption">Repair submissions: ${r.obstacle.tries.length} · ${r.obstacle.hint?'nudge used':'no repair nudge'}. +${r.awarded} arrival points this run. Challenge points are awarded when solved.</p>`:''}${route?window.TryvoJourneyPuzzles.receipt(r):''}${currentCase?`<details><summary>Current case work</summary>${currentCase}</details>`:''}${openRecord(r,route?'View this route':'Read full feedback')}
 ${records.length>1?`<details class="earlier-attempts"><summary>Earlier attempts (${records.length-1})</summary><ul>${records.slice(0,-1).reverse().map(x=>`<li><div><time datetime="${esc(x.date)}">${esc(dateText(x))}</time><span>${route?(x.success?'Arrived':'Needs revision')+' · '+x.cost+' credits':x.score+'/100 · '+esc(support(x))}</span></div>${openRecord(x,'View report')}</li>`).join('')}</ul></details>`:''}</div>`;
}
function progress(){
 const RE=window.TryvoRescueEngine,rescue=RE.valid(state.tram)?state.tram:null,completed=C.count(state);
 const rows=[...C.chapters,{id:D.check.id,title:'Independent check',skill:'Separate from festival progress',type:'mission',separate:true}];
 return `<section class="page progress-page"><div class="progress-heading"><div><h1>My progress</h1><p>Open a level to see your results and attempts.</p></div><a href="#explore">Back to the festival</a></div>
 ${window.TryvoMindScore.card(state)}<section class="level-progress-overview" aria-label="Festival progress"><div><h2>Lantern Festival</h2><strong>${completed}<span> / 12 tram journeys completed</span></strong></div><progress value="${completed}" max="12" aria-label="Tram journeys completed">${completed} of 12</progress><p>A journey counts when the tram arrives and its checkpoint is resolved. Replays do not add completion.</p></section>
 <section class="level-reports" id="festival-file" aria-label="Level reports">${rows.map((c,i)=>{
  const records=c.type==='route'?(rescue?.history||[]).filter(r=>r.level===c.id):state.history.filter(r=>r.taskId===c.id),done=c.separate?records.length>0:C.done(state,c.id),inProgress=state.active?.taskId===c.id&&state.active.phase!=='result'||c.type==='route'&&(rescue?.drafts[c.id]?.path.length>1||records.length>0),changed=false;
  const status=done?'Complete':inProgress?'In progress':'Not started';
  return `<details class="level-report ${c.separate?'separate-check':''}" name="level-reports" id="progress-${c.id}"><summary><span class="level-number ${done?'is-complete':''}" aria-hidden="true">${c.separate?'◇':done?'✓':i+1}</span><span class="level-title"><strong>${esc(c.title)}</strong><small>${esc(c.skill)}</small></span><span class="level-status ${done?'is-complete':''}">${status}</span><span class="level-chevron" aria-hidden="true">⌄</span></summary><div class="level-report-body">${changed?'<p class="level-feedback">Your venue choice changed. Run the final delivery again to complete the current plan; earlier arrivals remain recorded below.</p>':''}${levelReport(c,records)}${c.separate?'<p class="caption">This separate task does not establish general improvement.</p>':''}<div class="level-actions">${state.active?.taskId===c.id&&state.active.phase!=='result'?btn('Resume attempt','resume'):c.separate?btn(records.length?'Revisit check':'Open check','start',`data-id="${c.id}"`,true):C.available(state,c.id)?C.launch(state,c,done?'Revisit level':'Open level'):'<span class="caption">Continue the earlier festival chapters to unlock this level.</span>'}</div></div></details>`;
 }).join('')}</section>${state.rescue?.history?.length?`<details class="journey-index"><summary>Earlier route layouts · preserved records (${state.rescue.history.length})</summary><p class="caption">These attempts use earlier layouts. Their original results and earned points are retained.</p>${C.chapters.map(c=>{const old=state.rescue.history.filter(r=>r.level===c.id);return old.length?`<details class="level-report"><summary>${esc(c.title)}</summary><div class="level-report-body">${levelReport(c,old)}</div></details>`:'';}).join('')}</details>`:''}<details class="library-records journey-index"><summary>Free-practice investigation records</summary>${D.missions.map(m=>`<details class="level-report"><summary>${esc(m.title)}</summary><div class="level-report-body">${levelReport({id:m.id,type:'mission'},state.history.filter(r=>r.taskId===m.id))}</div></details>`).join('')}</details><details class="journey-index"><summary>Guided demo · ${Object.keys(state.tutorial?.completed||{}).length} / 2 lessons complete</summary><p>Practice lessons teach the controls and budget. They do not add festival completions or leaderboard points.</p><a href="#demo">Open guided lessons</a></details><p class="progress-storage">${storageOK?'Saved on this device.':'Session only: progress is not saved.'}</p></section>`;
}
function rankings(){
 const demo=[['Aanya',570],['Kabir',530],['Meera',480],['Arjun',420],['Zoya',360],['Dev',300],['Isha',250],['Rohan',200],['Tara',150],['Neel',100],['Sana',60],['Vihaan',25]];
 const score=window.TryvoRescueEngine.total(state),players=[...demo.map(([name,score],i)=>({name,score,id:i,you:false})),{name:'You',score,id:12,you:true}].sort((a,b)=>b.score-a.score||a.id-b.id);
 const rank=1+players.filter(p=>p.score>score).length,tied=players.filter(p=>p.score===score).length>1;
 return `<section class="page leaderboard-page"><div class="leaderboard-heading"><h1>Leaderboard</h1><span class="leaderboard-demo">Demo league</span></div><p class="leaderboard-intro">12 fictional players. Your score comes from your own attempts.</p>
 <div class="leaderboard-standing"><p>Your position <strong>${tied?'=':'#'}${rank}</strong><span>of ${players.length} players</span></p><button class="text-button" data-action="leaderboard-me">Find me in the table</button></div>
 <div class="leaderboard-table-wrap"><table class="leaderboard-table"><caption class="sr-only">Demo leaderboard, sorted by game points. Equal scores share a rank.</caption><thead><tr><th scope="col">Rank</th><th scope="col">Player</th><th scope="col">Game points</th></tr></thead><tbody>${players.map(p=>{
 const position=1+players.filter(x=>x.score>p.score).length,tie=players.filter(x=>x.score===p.score).length>1;
 return `<tr class="${p.you?'leaderboard-you':''}" ${p.you?'tabindex="-1" aria-label="Your leaderboard position"':''}><td><span class="leaderboard-rank ${position<=3?'top-rank':''}" aria-label="${tie?'Joint rank':'Rank'} ${position}">${tie?'=': ''}${position}</span></td><th scope="row"><span class="leaderboard-person"><span class="leaderboard-avatar ${p.you?'you-avatar':''}" aria-hidden="true">${p.you?'Y':p.name[0]}</span><span>${p.name}${p.you?'<small>Your actual score</small>':''}</span></span></th><td class="leaderboard-score">${p.score}</td></tr>`;
 }).join('')}</tbody></table></div>
 <details class="leaderboard-rules"><summary>How scoring works</summary><p>Each repaired obstruction and final dispatch earns 20 points, plus 10 if your first submission is correct without a nudge. Arrival earns 40; an efficient route earns 20; meeting a fare target earns 10. Each award is earned once per level. Replays cannot farm points. Earlier completed journeys retain their original 50 points. Your existing eligible investigation and independent-check points are preserved and added separately.</p><p>For the separate investigations, replays, hints, declared outside assistance and shared attempts do not add independent-attempt points. Your reports remain in My progress. Equal scores share a rank; the next rank skips the tied places.</p><p>The other players and their scores are fixed demo data. There are no live players or online scores. Game points do not measure intelligence.</p><a href="#progress">View my level reports</a></details></section>`;
}
function render(focus=true){lastRenderedHash=location.hash;window.dispatchEvent(new CustomEvent('tryvo:before-render',{detail:{focus}}));R.cancel();window.TryvoTutorial.cancel();if(focus){clearTimeout(toastTimer);$('#toast').textContent='';$('#toast').classList.remove('visible');}notice();let hash=location.hash.split('?')[0]||'#explore',html='';if(hash==='#result')resultId=new URLSearchParams(location.hash.split('?')[1]||'').get('id')||resultId;if(restoreBlocked)html=surface('Your saved record needs attention.','It has not been overwritten.',`<div class="empty-state"><p>You can start a fresh session without changing the existing saved record.</p>${btn('Start a fresh session','fresh-session')}</div>`);else if(hash==='#rescue')html=R.render();else if(hash==='#progress'||hash==='#festival-file')html=progress();else if(hash==='#demo')html=window.TryvoTutorial.home();else if(hash==='#demo-play')html=window.TryvoTutorial.render();else if(hash==='#mission-library')html=library();else if(hash==='#rankings')html=rankings();else if(hash==='#result'&&resultId){const r=state.history.find(r=>r.id===resultId);html=r?result(model(r.taskId,r),r):explore();}else if(hash==='#mission'&&state.active){const a=state.active,m=task();if(a.phase==='initial')html=initial(m,a);else if(a.phase.startsWith('handoff'))html=handoff(m,a);else if(a.phase==='investigate')html=investigation(m,a);else if(a.phase==='decision')html=decision(m,a);else if(a.phase==='check')html=decision(m,a,true);else {const r=state.history.find(r=>r.id===a.id);html=r?(m.type!=='check'&&!r.storySeen?story(m,r):result(m,r)):explore();}}else html=explore();$('#main').innerHTML=html;refreshPoints();window.TryvoFeedback.mount();filterLibrary();document.querySelectorAll('.main-nav a').forEach(a=>{if(a.getAttribute('href')===(hash==='#festival-file'?'#progress':['#demo','#demo-play','#mission-library'].includes(hash)?'#demo':['#progress','#rankings'].includes(hash)?hash:'#explore'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);} if(hash==='#festival-file'){const file=$('#main #festival-file');if(file){file.scrollIntoView({behavior:'instant'});}} }
function modal(title,body){$('#dialog').classList.remove('feedback-dialog');if($('#dialog').open)$('#dialog').close();$('#dialog').classList.remove('comparison-dialog');$('#dialog-content').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="close-button" data-action="close" aria-label="Close dialog">×</button></div>${body}`;$('#dialog').showModal();}
function start(id,force=false,acknowledged=false){const m=all.find(t=>t.id===id);if(!m){say('This mission is not available.');return;}if(state.active&&!['result'].includes(state.active.phase)&&!force){modal('You have an attempt in progress.',`<p>Starting another ends the current attempt. Returning to its task later counts as a replay.</p><div class="dialog-actions">${btn('Continue current attempt','resume')}${btn('Start another attempt','force-start',`data-id="${id}"`,true)}</div>`);return;}if(!acknowledged&&!state.seen[id]){modal('Before you enter this story',`<p>You can pause and resume this attempt. If you leave it to start another story, returning counts as a replay.</p><p>Hints and shared play still earn a complete contribution record. Independent points are available only on a first attempt without declared assistance.</p><div class="dialog-actions">${btn('Enter story','enter-story',`data-id="${id}"`)}${btn('Not now','close','',true)}</div>`);return;}if($('#dialog').open)$('#dialog').close();E.begin(state,m);resultId=null;compareIds=[];formError='';save();navigate('#mission');}
function error(e){formError=e.message||'This action is not available.';render(false);const node=$('.form-error');if(node){node.tabIndex=-1;node.focus();}else say(formError);}
function draft(form){const a=state.active;const fd=new FormData(form);if(form.id==='survey-form'){const r=resultId?state.history.find(r=>r.id===resultId):state.history.find(r=>r.id===a?.id);if(r){state.surveyDrafts[r.id]={attempt:r.id,earned:fd.get('earned'),enjoyment:fd.get('enjoyment')};save();}return;}if(!a)return;if(form.id==='initial-form')a.draftInitial={answer:fd.get('initial')||'',confidence:fd.get('confidence')||'',note:fd.get('note')||''};else if(form.id==='decision-form'){a.answer=fd.get('answer')||a.answer||'';a.next=task()?.plan?'separate':fd.get('next')||'';a.note=fd.has('note')?fd.get('note'):a.note||'';a.external=a.external||fd.has('external');}save();}
document.addEventListener('click',ev=>{
 const b=ev.target.closest('[data-campaign]');if(!b)return;
 const c=C.chapter(b.dataset.chapter);
 if(b.dataset.campaign==='finale'){modal('Your Lantern Festival',C.finale(state));return;}
 if(!c)return;
 if(b.dataset.campaign==='inspect'){
  const r=C.record(state,c.id),prior=C.chapters.slice(0,C.chapters.indexOf(c)).find(x=>!C.done(state,x.id));
  modal(esc(c.title),`<p class="caption">Lantern Festival · Chapter ${C.chapters.indexOf(c)+1} · ${esc(c.skill)}</p><p>${esc(c.why)}</p>${r?`<div class="campaign-record"><h3>Carried into your festival</h3><p>${esc(C.effect(state,c.id))}</p><p class="caption">${esc(C.status(state,c))}</p>${c.type==='mission'?btn('Inspect my reasoning','inspect-record',`data-id="${esc(r.id)}"`,true):`<button class="button secondary" data-rescue="watch-best" data-level="${c.id}">Inspect my route</button>`}</div>`:''}<div class="dialog-actions">${C.available(state,c.id)?C.launch(state,c):`<p>Continue <strong>${esc(prior?.title||'the previous chapter')}</strong> to reach this chapter.</p>${C.primary(state)}`}</div>`);return;
 }
 if(b.dataset.campaign==='play'){
  if(!C.available(state,c.id)){toast('Complete the earlier festival chapters first.');return;}
  if($('#dialog').open)$('#dialog').close();
  if(c.type==='route')R.enter(c.id);else if(state.active?.taskId===c.id&&state.active.phase!=='result')navigate('#mission');else start(c.id);
 }
});
document.addEventListener('input',ev=>{const f=ev.target.closest('#initial-form,#decision-form,#survey-form');if(f)draft(f);if(ev.target.id==='history-search'){historyQuery=ev.target.value;historyExpanded=false;rememberDashboard();updateHistory();}if(ev.target.id==='mission-search'){query=ev.target.value;rememberLibrary();filterLibrary(true);}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,a=state.active,m=task();try{
 if(action==='leaderboard-me'){const row=$('.leaderboard-you');row?.focus({preventScroll:true});row?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(action==='demo-controls'){modal('Demo controls',`<p>Progress is stored only in this browser. Reset clears this prototype’s attempts and view preferences.</p>${btn('Reset Demo','reset','',true)}<p class="caption">The earlier prototype and unrelated browser data are preserved.</p>`);return;}
 if(action==='browse-library'){navigate('#mission-library');return;}
 if(action==='inspect-record'){inspectRecord(b.dataset.id);return;}
 if(action==='compare-records'){compareRecords();return;}
 if(action==='clear-records'){recordCompare=[];render(false);$('[data-action="clear-records"]').focus({preventScroll:true});return;}
 if(action==='more-history'){historyExpanded=true;updateHistory();say('All matching attempts shown.');$('#history-records').tabIndex=-1;$('#history-records').focus({preventScroll:true});return;}
 if(action==='clear-history'){historyExpanded=false;historyQuery='';historyTask='all';historyCondition='all';rememberDashboard();render(false);$('#history-search').focus();return;}
 if(action==='rank-view'){showSamples=b.dataset.view==='examples';recordCompare=[];rememberDashboard();render(false);$('[data-action="rank-view"]').focus({preventScroll:true});return;}
 if(action==='close'){const comparisonWasOpen=$('#dialog').classList.contains('comparison-dialog');$('#dialog').close();$('#dialog').classList.remove('comparison-dialog');if(comparisonWasOpen){render(false);$('.compare-launch')?.focus({preventScroll:true});}return;}
 if(action==='review-stage'){reviewStage(b.dataset.stage,b.dataset.record);return;}
 if(action==='reset-filters'){query='';availability='all';district='all';rememberLibrary();render(false);$('#mission-search').focus({preventScroll:true});filterLibrary(true);return;}
 if(action==='build-plan'){draft($('#decision-form'));if(!m.options.some(o=>o.id===a.answer))throw Error('Choose a conclusion before building the plan.');const pins=a.mode==='coop'?a.pinned.flat():a.pinned[0];for(const l of m.links){const v=a.reasoning[l.id];if(!v||!pins.includes(v.source)||!l.options.some(o=>o.id===v.meaning))throw Error('Complete both source–interpretation connections before building the plan.');}a.decisionPanel='plan';formError='';save();render();return;}
 if(action==='review-interpretation'){draft($('#decision-form'));a.decisionPanel='reasoning';formError='';save();render();return;}
 if(action==='compare'){comparison();return;}
 if(action==='reveal'){const r=state.history.find(r=>r.id===a?.id);if(r){r.storySeen=true;save();render();}return;}
 if(action==='reset'){modal('Reset this Tryvo demo?',`<p>This clears this version’s mission attempts, Festival Rescue routes, reflections and progress points on this browser. Other projects and the earlier Tryvo prototype are unaffected.</p><p>Resetting does not make a previously seen challenge unfamiliar.</p><div class="dialog-actions">${btn('Cancel','close','',true)}${btn('Reset Demo','confirm-reset')}</div>`);return;}
 if(action==='confirm-reset'){let cleared=false;try{localStorage.removeItem(KEY);cleared=true;storageOK=true;}catch{storageOK=false;}restoreBlocked=false;state=E.fresh();resultId=null;district='all';query='';availability='all';rankTask='attendance';rankSupport='all';showSamples=false;historyExpanded=false;historyQuery='';historyTask='all';historyCondition='all';recordCompare=[];clearTimeout(toastTimer);$('#toast').textContent='';$('#toast').classList.remove('visible');formError='';compareIds=[];$('#dialog').close();navigate('#explore');say(cleared?'Demo reset.':'Session reset. Saved state could not be cleared because storage is blocked.');if(!cleared)$('#notice').innerHTML='<div class="notice">This session was reset, but the saved record could not be cleared. Browser storage is blocked.</div>';return;}
 if(action==='enter-story'){$('#dialog').close();start(b.dataset.id,false,true);return;}
 if(action==='start')start(b.dataset.id);
 else if(action==='force-start'){$('#dialog').close();start(b.dataset.id,true);}
 else if(action==='resume'){if($('#dialog').open)$('#dialog').close();formError='';navigate('#mission');}
 else if(action==='explore')navigate('#explore');
 else if(action==='fresh-session'){restoreBlocked=false;storageOK=false;state=E.fresh();render();}
 else if(action==='district'){district=b.dataset.id;rememberLibrary();render(false);filterLibrary(true);$('#mission-library').scrollIntoView({behavior:'instant'});$('.library h1').tabIndex=-1;$('.library h1').focus({preventScroll:true});}
 else if(action==='switch-mode'){if(a.phase!=='initial'||a.initials.length)throw Error('Choose a mode before recording your first judgment.');a.mode=b.dataset.mode;a.draftInitial=null;save();render();}
 else if(action==='handoff'){if(a.phase==='handoff-initial'){a.turn=1;a.phase='initial';a.draftInitial=null;}else if(a.phase==='handoff-evidence'){a.turn=1;a.phase='investigate';a.evidence=m.evidence.find(e=>e.group===1).id;}save();render();}
 else if(action==='evidence'){E.view(a,m,b.dataset.id);save();render(false);$('.evidence-detail').tabIndex=-1;$('.evidence-detail').focus({preventScroll:true});}
 else if(action==='pin'||action==='pin-check'){const form=$('#decision-form');if(form)draft(form);E.pin(a,m,b.dataset.id);if(m.links&&!a.pinned[a.turn].includes(b.dataset.id)){for(const v of Object.values(a.reasoning))if(v.source===b.dataset.id&&v.by===a.turn)v.source='';}save();render(false);const replacement=document.querySelector(`[data-action="${action}"][data-id="${b.dataset.id}"]`);replacement?.focus({preventScroll:true});toast((a.pinned[a.turn].includes(b.dataset.id)?'Selected: ':'Removed: ')+m.evidence.find(e=>e.id===b.dataset.id).title);}
 else if(action==='hint'){if(a.phase!=='investigate')return;a.hint=true;save();render(false);$('.hint-box').tabIndex=-1;$('.hint-box').focus({preventScroll:true});say('Hint revealed. This is now an assisted attempt.');}
 else if(action==='decide'){if(!a.pinned[a.turn].length)throw Error('Select at least one piece of supporting evidence before continuing.');if(a.mode==='coop'&&m.links){const l=m.links.find(l=>l.owner===a.turn),v=a.reasoning[l.id];if(!v||!a.pinned[a.turn].includes(v.source)||!l.options.some(o=>o.id===v.meaning))throw Error('Record your source and interpretation before passing the investigation on.');}if(a.mode==='coop'&&a.turn===0)a.phase='handoff-evidence';else a.phase='decision';formError='';save();render();toast(a.phase==='handoff-evidence'?'Your evidence is recorded. Pass the device to your partner.':'Now choose your conclusion, explain your source connections and plan a next step.');}
 else if(action==='back-evidence'){a.phase='investigate';a.decisionPanel='reasoning';a.turn=a.mode==='coop'?1:0;formError='';save();render();}
 else if(action==='inspect'){const record=state.history.find(r=>r.id===(resultId||state.active?.id));const mt=model(b.dataset.task,record),e=mt.evidence.find(x=>x.id===b.dataset.id);modal(esc(e.title),evidenceBody(e));}
 else if(action==='history'){if($('#dialog').open)$('#dialog').close();resultId=b.dataset.id;navigate('#result?id='+encodeURIComponent(resultId));}
 else if(action==='samples'){showSamples=true;recordCompare=[];rememberDashboard();render(false);$('[data-action="samples"]').focus({preventScroll:true});}
 else if(action==='about')modal('A world to practise in.',`<p>Tryvo is a self-contained concept prototype for a 2040 world of personal AI agents. The missions, figures, outcomes and rubrics are authored illustrations.</p><p>Festival Rescue has three playable route puzzles, with local records and retries. Five investigation missions and a separate independent check are also playable; twenty entries are upcoming. Shared play uses one device. Duels use a scripted opponent. Ranking examples are explicitly fictional.</p><p>MindScore counts eligible game-progress points. It does not measure intelligence, brain health or proven improvement. Assistance is self-reported.</p><p>Nothing is sent to a server. Progress stays in this browser when local saving is available.</p>`);
 else if(action==='campaign-interest'){state.campaignInterest=b.dataset.kind;save();$('#interest-status').textContent=storageOK?'Preference saved locally. No signup or payment.':'Preference recorded for this session. No signup or payment.';}
 else if(action==='membership')modal('A campaign worth coming back for.',`<p><strong>Free starter route:</strong> The empty seats, The reminder trial and The bigger stall, with contribution feedback.</p><p><strong>Campaign concept:</strong> a linked series about organising a neighbourhood festival, with reviewed evidence, a new decision in each chapter and fresh independent checks. Additional chapters are not built.</p><p><strong>Club concept:</strong> facilitated group sessions with complementary evidence and shared debriefs. A future organisational licence would have a different buyer from an individual campaign.</p><p>No subscription, purchase, account or price is active. Demand, content-production cost and pricing remain untested.</p><div class="dialog-actions">${btn('I would explore a campaign','campaign-interest','data-kind="campaign"')}${btn('I would explore club sessions','campaign-interest','data-kind="club"',true)}</div><p id="interest-status" role="status">Optional demo preference, saved only in this browser. Not a reservation.</p>`);
}catch(e){error(e);}});
document.addEventListener('submit',ev=>{if(!['initial-form','decision-form','survey-form'].includes(ev.target.id))return;ev.preventDefault();const fd=new FormData(ev.target),a=state.active,m=task();try{if(ev.target.id==='initial-form'){draft(ev.target);E.commitInitial(a,m,fd.get('initial'),fd.get('confidence'),fd.get('note'));a.draftInitial=null;formError='';save();render();toast(a.phase.startsWith('handoff')?'First judgment recorded. Pass the device to your partner.':'First judgment recorded. Now explore the clues and select your evidence.');}else if(ev.target.id==='decision-form'){draft(ev.target);const r=E.finish(state,m,a.answer,a.next,a.note,a.external);formError='';resultId=r.id;save();render();window.TryvoFeedback.mission(m,r);}else{const r=resultId?state.history.find(r=>r.id===resultId):state.history.find(r=>r.id===a?.id);if(!fd.get('earned')&&!fd.get('enjoyment')){$('#survey-status').textContent='Choose at least one rating, or skip this optional reflection.';return;}state.surveys[r.id]={attempt:r.id,earned:fd.get('earned'),enjoyment:fd.get('enjoyment')};delete state.surveyDrafts[r.id];save();$('#survey-status').textContent=storageOK?'Reflection saved on this device.':'Reflection recorded for this session.';toast(storageOK?'Reflection saved on this device.':'Reflection recorded for this session only.');}}catch(e){error(e);}});
document.addEventListener('toggle',ev=>{const node=ev.target;if(!node.isConnected||!node.matches?.('.connection-editor')||!node.open)return;node.parentElement.querySelectorAll('.connection-editor').forEach(other=>{if(other!==node)other.open=false;});if(state.active&&state.active.phase!=='result'){state.active.connectionOpen=node.dataset.link;save();}},true);
document.addEventListener('change',ev=>{
 if(ev.target.id==='history-task'||ev.target.id==='history-condition'){if(ev.target.id==='history-task')historyTask=ev.target.value;else historyCondition=ev.target.value;historyExpanded=false;rememberDashboard();updateHistory();return;}
 if(ev.target.hasAttribute('data-record-compare')){const id=ev.target.value,r=state.history.find(r=>r.id===id),first=state.history.find(r=>r.id===recordCompare[0]);if(ev.target.checked){if(recordCompare.length===2||first&&(first.taskId!==r.taskId||versionOf(first)!==versionOf(r))){ev.target.checked=false;$('#compare-record-status').textContent=recordCompare.length===2?'Two attempts already selected. Clear one to choose another.':'Choose the same task and content version; clear your selection to switch tasks.';return;}recordCompare.push(id);}else recordCompare=recordCompare.filter(x=>x!==id);$('#compare-record-status').textContent=recordCompare.length+' of 2 attempts selected. Same task and content version only.';$('[data-action="compare-records"]').disabled=recordCompare.length!==2;return;}

 if(ev.target.dataset.connection){const a=state.active,m=task(),l=m?.links?.find(l=>l.id===ev.target.dataset.connection);if(!a||!l||a.phase==='result')return;if(a.mode==='coop'&&(a.phase!=='investigate'||l.owner!==a.turn))return;if(ev.target.dataset.part==='source'){
  const id=ev.target.value,source=m.evidence.find(e=>e.id===id);
  if(id&&(!source||a.mode==='coop'&&source.group!==a.turn))return;
  const form=$('#decision-form');if(form)draft(form);
  const added=id&&!a.pinned[a.turn].includes(id);
  if(id){if(added)E.pin(a,m,id);else E.view(a,m,id);}
  const connection=a.reasoning[l.id]||{source:'',meaning:'',by:a.mode==='coop'?a.turn:0};
  connection.source=id;a.reasoning[l.id]=connection;a.connectionOpen=l.id;save();render(false);
  $('#source-'+l.id)?.focus({preventScroll:true});
  if(added)toast(source.title+' added to your supporting evidence.');
  return;
 }
 const v=a.reasoning[l.id]||{source:'',meaning:'',by:a.mode==='coop'?a.turn:0};v[ev.target.dataset.part]=ev.target.value;a.reasoning[l.id]=v;save();const editor=ev.target.closest('.connection-editor');editor.querySelector('[data-link-status]').textContent=v.source&&v.meaning?'Recorded':'Needs your input';const source=m.evidence.find(e=>e.id===v.source);if(ev.target.dataset.part==='source')$('#preview-'+l.id).innerHTML=source?`<details><summary>Read ${esc(source.title)}</summary>${evidenceBody(source)}</details>`:'<p>Select a source to read it here.</p>';const visible=[...editor.parentElement.querySelectorAll('.connection-editor')];$('.connection-count').textContent=visible.filter(n=>{const pair=a.reasoning[n.dataset.link];return pair?.source&&pair?.meaning;}).length+' of '+visible.length+' connections recorded';return;}
 if(ev.target.dataset.plan){const a=state.active,m=task();if(a?.phase!=='decision'||!m.plan)return;a.plan[ev.target.dataset.plan]=ev.target.value;save();$('#plan-preview').innerHTML=planBoard(m,a.plan);return;}
 if(ev.target.id==='mission-availability'){availability=ev.target.value;rememberLibrary();filterLibrary(true);return;}if(ev.target.name==='compare-clue'){const id=ev.target.value;if(ev.target.checked){if(compareIds.length===2){ev.target.checked=false;$('#compare-status').textContent='Remove one clue before choosing another.';return;}compareIds.push(id);}else compareIds=compareIds.filter(x=>x!==id);comparison();document.querySelector('[name="compare-clue"][value="'+id+'"]')?.focus();return;}if(ev.target.id==='rank-task'){rankTask=ev.target.value;recordCompare=[];rememberDashboard();render(false);$('#rank-task').focus({preventScroll:true});}else if(ev.target.id==='rank-support'){rankSupport=ev.target.value;recordCompare=[];rememberDashboard();render(false);$('#rank-support').focus({preventScroll:true});}});
$('#dialog').addEventListener('cancel',ev=>{ev.preventDefault();$('#dialog [data-action="close"]').click();});
$('#dialog').addEventListener('close',()=>{const wasComparison=$('#dialog').classList.contains('comparison-dialog');$('#dialog').classList.remove('comparison-dialog');if(wasComparison){render(false);$('.compare-launch')?.focus({preventScroll:true});}else if(!$('#dialog').open&&(document.activeElement===document.body||$('#dialog').contains(document.activeElement))){$('#run-outcome')?.focus({preventScroll:true});if(!$('#run-outcome'))$('#main').focus({preventScroll:true});}});
window.addEventListener('hashchange',()=>{if(location.hash===lastRenderedHash)return;formError='';render();});
document.querySelectorAll('.main-nav a').forEach((link,i)=>{link.innerHTML=icon(['route','chart','people','grid'][i],20)+'<span>'+link.textContent+(i===3?'<small>Learn how to play</small>':'')+'</span>';});
window.TryvoFeedback.configure({getState:()=>state,modal});
R.configure({getState:()=>state,save,render,navigate,toast,modal});
window.TryvoTutorial.configure({getState:()=>state,save,render,navigate,toast,modal});
window.TryvoMindScore.configure({getState:()=>state,save,render,navigate,modal});
render(false);
})();
